pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[2] memory addrs, uint112[2] memory amounts) public {
        vm.assume(addrs[0] != address(0) && addrs[1] != address(0));
        vm.assume(addrs[0] != addrs[1]);
        uint256 sumBefore;
        for (uint256 i = 0; i < 2; i++) {
            vm.deal(addrs[i], amounts[i]);
            vm.prank(addrs[i]);
            (bool ok, ) = address(c).call{value: amounts[i]}("");
            require(ok);
            sumBefore += amounts[i];
        }
        uint256 contractBalBefore = address(c).balance;
        assertTrue(contractBalBefore == sumBefore);
        // now withdraw for each
        for (uint256 i = 0; i < 2; i++) {
            vm.prank(addrs[i]);
            c.withdraw();
        }
        uint256 sumAfter;
        for (uint256 i = 0; i < 2; i++) {
            sumAfter += c.balances(addrs[i]);
        }
        uint256 contractBalAfter = address(c).balance;
        assertTrue(sumAfter == contractBalAfter);
    }
}

