import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmount) public {
        // Bound deposit amount to avoid overflow
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));
        depositAmount = bound(depositAmount, 1, 1e18);

        // Fund the contract
        vm.deal(address(this), depositAmount);

        // Deposit to the caller via fallback
        vm.prank(caller);
        (bool sent, ) = address(c).call{value: depositAmount}("");
        require(sent, "deposit failed");

        uint256 callerBalanceBefore = c.balances(caller);

        // Now withdraw
        vm.prank(caller);
        c.withdraw();

        // After withdraw in P: caller's balance is 0 and they got the ether
        // After withdraw in M: caller's balance is 0 but they got 0 ether
        // So the invariant: caller's balance is always 0 after withdraw
        assertTrue(c.balances(caller) == 0);
    }
}

