pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 amount) public {
        vm.assume(sender != address(0));
        vm.deal(sender, amount);
        vm.prank(sender);
        (bool success, ) = address(c).call{value: amount}("");
        require(success);

        uint256 initialBalance = address(sender).balance;
        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The bugged version removes the lock, allowing reentrancy which may cause revert or different balance outcome.
        // The reference version always completes withdraw successfully (no revert) when sender has balance.
        // Bugged version may revert due to reentrancy attempt or fail assertions.
        assertTrue(!reverted, "Withdraw should not revert in reference implementation");

        // Additionally, after successful withdraw, sender gets their balance back and contract balance becomes 0.
        assertEq(address(sender).balance, initialBalance + c.balances(sender));
        assertEq(address(c).balance, 0);
    }
}

