pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address alice = address(0x1234);

    function setUp() public {
        c = new C();
        vm.deal(alice, 1 ether);
    }

    function testFuzz_property(uint256 depositAmount) public {
        vm.assume(depositAmount > 0 && depositAmount <= address(this).balance);

        // Alice deposits via fallback
        vm.prank(alice);
        (bool successDeposit, ) = address(c).call{value: depositAmount}("");
        assertTrue(successDeposit, "Deposit failed");

        // Before withdraw, lock must be false (unlocked) — cannot read directly, so we infer by the fact that withdraw can be called again
        // After withdraw, lock must be false again so the next withdraw succeeds
        vm.prank(alice);
        (bool successFirst, ) = address(c).call(abi.encodeWithSignature("withdraw()"));
        assertTrue(successFirst, "First withdraw should succeed");

        // Second withdraw should also succeed if lock is properly reset to false
        vm.prank(alice);
        (bool successSecond, ) = address(c).call(abi.encodeWithSignature("withdraw()"));
        assertTrue(successSecond, "Second withdraw should succeed in reference, must fail in buggy");
    }
}

